CREATE TABLE revenue_rules(id BINARY(16) PRIMARY KEY,contract_id BINARY(16) NOT NULL,game_id BINARY(16) NOT NULL,name VARCHAR(255) NOT NULL,status VARCHAR(30) NOT NULL);
CREATE TABLE revenue_rule_versions(id BINARY(16) PRIMARY KEY,rule_id BINARY(16) NOT NULL,version_number INT NOT NULL,effective_from DATE NOT NULL,effective_to DATE,calculation_method VARCHAR(30) NOT NULL,platform_share DECIMAL(8,5) NOT NULL,studio_share DECIMAL(8,5) NOT NULL,publisher_share DECIMAL(8,5) NOT NULL,client_share DECIMAL(8,5) NOT NULL,UNIQUE(rule_id,version_number),FOREIGN KEY(rule_id) REFERENCES revenue_rules(id) ON DELETE CASCADE);